"""Advanced SubStation Alpha (.ass / .ssa) parser and writer implementation."""

from __future__ import annotations

import re

from subtitle_tools.parsers.base import BaseSubtitleParser, BaseSubtitleWriter
from subtitle_tools.time import format_ass_time, parse_time
from subtitle_tools.types import Cue, SubtitleDocument

DEFAULT_SCRIPT_INFO: list[str] = [
    "; Script generated by subtitle-tools",
    "Title: Subtitle",
    "ScriptType: v4.00+",
    "WrapStyle: 0",
    "ScaledBorderAndShadow: yes",
]

DEFAULT_STYLES_FORMAT = (
    "Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, "
    "OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, "
    "ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, "
    "Alignment, MarginL, MarginR, MarginV, Encoding"
)

DEFAULT_STYLE_LINE = (
    "Style: Default,Arial,20,&H00FFFFFF,&H000000FF,&H00000000,&H00000000,"
    "0,0,0,0,100,100,0,0,1,2,2,2,10,10,10,1"
)

DEFAULT_EVENTS_FORMAT = "Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text"


class AssParser(BaseSubtitleParser):
    """Parser for ASS/SSA subtitle files preserving Styles, Events, and unknown sections verbatim."""

    def parse(self, text: str) -> SubtitleDocument:
        normalized = text.replace("\r\n", "\n").replace("\r", "\n")
        lines = normalized.split("\n")

        current_section: str | None = None
        script_info_lines: list[tuple[str, str]] = []
        styles_lines: list[str] = []
        events_format: list[str] = []
        unknown_sections: list[tuple[str, list[str]]] = []
        cues: list[Cue] = []

        current_unknown_name: str | None = None
        current_unknown_lines: list[str] = []

        def flush_unknown() -> None:
            nonlocal current_unknown_name, current_unknown_lines
            if current_unknown_name is not None:
                unknown_sections.append((current_unknown_name, list(current_unknown_lines)))
                current_unknown_name = None
                current_unknown_lines = []

        for raw_line in lines:
            line = raw_line.strip()
            # Check section header
            if line.startswith("[") and line.endswith("]"):
                flush_unknown()
                current_section = line.lower()
                if current_section not in ("[script info]", "[v4+ styles]", "[v4 styles]", "[events]"):
                    current_unknown_name = line
                continue

            if not line:
                if current_unknown_name is not None:
                    current_unknown_lines.append(raw_line)
                continue

            if current_section == "[script info]":
                if line.startswith(";"):
                    script_info_lines.append((";", line[1:].strip()))
                elif ":" in line:
                    key, val = line.split(":", 1)
                    script_info_lines.append((key.strip(), val.strip()))
                else:
                    script_info_lines.append(("", line))

            elif current_section in ("[v4+ styles]", "[v4 styles]"):
                styles_lines.append(line)

            elif current_section == "[events]":
                if line.startswith("Format:"):
                    cols = [c.strip().lower() for c in line.split(":", 1)[1].split(",")]
                    events_format = cols
                elif line.startswith("Dialogue:") or line.startswith("Comment:"):
                    # Only parse Dialogue as cues (Comments can be stored if needed)
                    is_dialogue = line.startswith("Dialogue:")
                    prefix, rest = line.split(":", 1)
                    if not events_format:
                        events_format = [
                            "layer", "start", "end", "style", "name",
                            "marginl", "marginr", "marginv", "effect", "text"
                        ]

                    # Split by comma up to len(events_format) - 1
                    num_fields = len(events_format)
                    parts = rest.split(",", num_fields - 1)
                    if len(parts) < num_fields:
                        continue

                    data = {events_format[i]: parts[i].strip() for i in range(len(parts) - 1)}
                    # The last field is 'text' (may contain commas and formatting)
                    text_content = parts[-1]

                    # Convert \N and \n in ASS to real newlines
                    text_content = text_content.replace(r"\N", "\n").replace(r"\n", "\n")

                    try:
                        start_ms = parse_time(data.get("start", "0:00:00.00"))
                        end_ms = parse_time(data.get("end", "0:00:00.00"))
                    except ValueError:
                        continue

                    layer_val = 0
                    try:
                        layer_val = int(data.get("layer", "0"))
                    except ValueError:
                        pass

                    margin_l = int(data.get("marginl", "0")) if data.get("marginl", "0").isdigit() else 0
                    margin_r = int(data.get("marginr", "0")) if data.get("marginr", "0").isdigit() else 0
                    margin_v = int(data.get("marginv", "0")) if data.get("marginv", "0").isdigit() else 0

                    if is_dialogue:
                        cues.append(
                            Cue(
                                start=start_ms,
                                end=end_ms,
                                text=text_content,
                                index=len(cues) + 1,
                                style=data.get("style", "Default"),
                                actor=data.get("name", ""),
                                margin_l=margin_l,
                                margin_r=margin_r,
                                margin_v=margin_v,
                                effect=data.get("effect", ""),
                                layer=layer_val,
                            )
                        )

            elif current_unknown_name is not None:
                current_unknown_lines.append(raw_line)

        flush_unknown()

        return SubtitleDocument(
            format="ass",
            cues=cues,
            ass_script_info=script_info_lines,
            ass_styles=styles_lines,
            ass_events_format=events_format or [c.strip().lower() for c in DEFAULT_EVENTS_FORMAT.split(":", 1)[1].split(",")],
            ass_unknown_sections=unknown_sections,
        )


class AssWriter(BaseSubtitleWriter):
    """Writer for ASS/SSA subtitle files preserving unknown sections."""

    def write(self, doc: SubtitleDocument) -> str:
        sections: list[str] = []

        # 1. Script Info
        script_info_lines = ["[Script Info]"]
        if doc.ass_script_info:
            for k, v in doc.ass_script_info:
                if k == ";":
                    script_info_lines.append(f"; {v}")
                elif k:
                    script_info_lines.append(f"{k}: {v}")
                else:
                    script_info_lines.append(v)
        else:
            script_info_lines.extend(DEFAULT_SCRIPT_INFO)
        sections.append("\n".join(script_info_lines))

        # 2. Styles
        styles_lines = ["[V4+ Styles]"]
        if doc.ass_styles:
            styles_lines.extend(doc.ass_styles)
        else:
            styles_lines.append(DEFAULT_STYLES_FORMAT)
            styles_lines.append(DEFAULT_STYLE_LINE)
        sections.append("\n".join(styles_lines))

        # 3. Preserved unknown sections
        for sec_name, sec_lines in doc.ass_unknown_sections:
            sec_block = [sec_name]
            sec_block.extend(sec_lines)
            sections.append("\n".join(sec_block))

        # 4. Events
        events_lines = ["[Events]"]
        events_lines.append(DEFAULT_EVENTS_FORMAT)
        for cue in doc.cues:
            # Replace newlines with ASS \N
            ass_text = cue.text.replace("\r\n", r"\N").replace("\n", r"\N")
            start_str = format_ass_time(cue.start)
            end_str = format_ass_time(cue.end)
            style = cue.style or "Default"
            actor = cue.actor or ""
            effect = cue.effect or ""
            line = (
                f"Dialogue: {cue.layer},{start_str},{end_str},{style},"
                f"{actor},{cue.margin_l},{cue.margin_r},{cue.margin_v},{effect},{ass_text}"
            )
            events_lines.append(line)
        sections.append("\n".join(events_lines))

        return "\n\n".join(sections) + "\n"
